NEW_FILES = {'tests/service/test_brief_fields.py': '"""The Level Standard\'s designer brief on the Level tab (0.253.0; the walker\'s section 16, docs/LEVEL_STANDARD.md).\n\nPLAYERS is a real control: the brief\'s ``crew_size``, which Lot reads to place one spawn per crew member and Laser\nTag reads as the crew it plays, so changing it rebuilds the layouts. The standard\'s FANTASY, SCALE, DENSITY, TONE and\nPLAYSTYLE have no reader yet: they are intent, saved and reopened with the design and kept out of the pipeline\'s\nbrief. A design saved before this release, without Players, builds exactly as it did. FAILS ON 0.252.0.\n"""\nimport json\nimport sys\nfrom pathlib import Path\n\nimport pytest\n\nROOT = Path(__file__).resolve().parents[2]\nsys.path.insert(0, str(ROOT))\n\nfrom apps.cli.commands import _brief_model  # noqa: E402\nfrom packages.service import design, operations, schemas  # noqa: E402\n\nT = "restaurant_row"\nSTANDARD = ("fantasy", "scale", "density", "tone", "playstyle")\n_NOOP = type("E", (), {"emit": lambda self, *a, **k: None})()\n\n\ndef _controls():\n    return {c["key"]: c for c in design.capabilities(T)}\n\n\ndef test_players_is_the_crew_lot_and_laser_tag_read():\n    c = _controls()["crew_size"]\n    assert (c["label"], c["support"], c["min"], c["max"], c["default"], c["rebuilds"]) == (\n        "Players", "supported", 1, 4, 4, "layout")\n    brief = design.brief_from_design(design.new_design(T, "t", {"crew_size": 2}))\n    assert brief["crew_size"] == 2 and _brief_model(brief).crew_size == 2\n    for bad in (0, 5, True, "4"):\n        with pytest.raises(design.DesignError):\n            design.new_design(T, "t", {"crew_size": bad})\n\n\ndef test_changing_players_rebuilds_the_layouts():\n    old = design.new_design(T, "t")\n    new = design.update_design(old, 1, choices={"crew_size": 3})\n    assert design.rebuilds_between(old, new) == ["layout"]\n\n\ndef test_the_standards_brief_is_intent_kept_out_of_the_pipeline():\n    c = _controls()\n    for key in STANDARD:\n        assert c[key]["support"] == "intent" and "nothing builds from it" in c[key]["note"]\n    words = {"fantasy": "Rob the deli\'s office safe after close and leave by the alley.", "scale": "small",\n             "density": "medium-high", "tone": "familiar, worn, warm", "playstyle": "stealth, then loud"}\n    brief = design.brief_from_design(design.new_design(T, "t", intent=words))\n    assert not set(STANDARD) & set(brief)\n    assert brief == design.brief_from_design(design.new_design(T, "t"))     # it changes nothing built\n\n\ndef test_the_brief_is_saved_and_reopened(tmp_path, monkeypatch):\n    from packages.tools import discovery\n    monkeypatch.setattr(discovery, "factory_root", lambda start=None: tmp_path)\n    got = operations.create_design({"template": T, "name": "Brief", "choices": {"crew_size": 2},\n                                    "intent": {"fantasy": "Crack the safe", "tone": "worn"}}, _NOOP)\n    opened = operations.open_design({"path": got["path"]}, _NOOP)\n    assert opened["problems"] == [] and opened["unknown_fields"] == []\n    d = opened["design"]\n    assert d["choices"]["crew_size"] == 2 and d["intent"]["fantasy"] == "Crack the safe" and d["intent"]["tone"] == "worn"\n    assert schemas.check(d, "gabagool.design.v1") == []\n\n\ndef test_a_design_saved_before_players_builds_as_it_did():\n    old = json.loads((Path(__file__).resolve().parent / "fixtures" / "authoring" / "design.json").read_text(\n        encoding="utf-8"))\n    assert "crew_size" not in old["choices"]\n    assert design.validate(old) == ([], [])\n    brief = design.brief_from_design(old)\n    assert "crew_size" not in brief and _brief_model(brief).crew_size == 4\n'}
CHANGELOG = '## [0.253.0] - the Level Standard\'s designer brief on the Level tab\n\n**The walker\'s designer brief (section 16 of `docs/LEVEL_STANDARD.md`\'s spine) as controls**, each saying truthfully\nwhether it changes what is built.\n\n### Added\n- **Players** (`crew_size`, 1-4, default 4, the brief model\'s own default): a supported control. Lot places one spawn\n  per crew member (`lot/site_spawns.crew_spawns`) and Laser Tag plays that crew, so changing it rebuilds the\n  layouts.\n- **Fantasy, Scale, Density, Tone, Playstyle**: intent, saved and reopened with the design.\n  - Each says what it asks for and that nothing builds from it yet.\n  - They are kept out of the pipeline\'s brief, which has no field for them (`design.STANDARD_INTENT`).\n- The brief\'s other fields already have controls: Heist and Location are the template, Streets and Beyond the edge;\n  Time is Time of day. Target session is the template\'s `target_minutes`, which Lot\'s pacing estimate is measured\n  against; it changes nothing built and stays out of the form.\n\n### Compatibility\n- A design saved before this release has no Players. Its brief carries no `crew_size`, so it builds with the default\n  4 exactly as before, and it reads without problems.\n\n### Tests\n- `tests/service/test_brief_fields.py` (4 of 5 fail on 0.252.0; the fifth guards the older design and passes on\n  both):\n  - Players reaches the brief model, refuses 0, 5, true and "4", and rebuilds the layouts when changed;\n  - the five intent fields change nothing built;\n  - the brief is saved and reopened, schema-valid;\n  - a design from before Players builds as it did.\n- `tests/service/test_design.py`\'s intent census includes the five.\n\n'
OLD_VERSION, NEW_VERSION = '0.252.0', '0.253.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        # 0.243.0 adds whole folders (apps/godot/): a new file's folder is made, never assumed
        (LF / name).parent.mkdir(parents=True, exist_ok=True)
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
